-- Rentals Phase 43: internal reminder queue. Delivery integration remains deferred.
begin;
create table public.rental_collection_preferences(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),tenancy_id uuid not null unique references public.rental_tenancies(id),channel text not null default 'email' check(channel in('email','sms','whatsapp','none')),timezone text not null default 'Africa/Johannesburg',suppressed_until timestamptz,suppression_reason text,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table public.rental_collection_reminders(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),tenancy_id uuid not null references public.rental_tenancies(id),reminder_stage text not null check(reminder_stage in('current','overdue_7','overdue_30','overdue_60','overdue_90')),channel text not null check(channel in('email','sms','whatsapp')),status text not null default 'queued' check(status in('queued','sent','suppressed','cancelled')),balance_snapshot numeric(14,2) not null,scheduled_for timestamptz not null default now(),sent_at timestamptz,suppressed_reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create index rental_collection_reminders_tenancy_idx on public.rental_collection_reminders(tenancy_id,created_at desc); create unique index rental_collection_reminders_daily_dedupe_idx on public.rental_collection_reminders(tenancy_id,reminder_stage,(scheduled_for::date)); alter table public.rental_collection_preferences enable row level security; alter table public.rental_collection_reminders enable row level security; revoke all on public.rental_collection_preferences,public.rental_collection_reminders from anon,authenticated; grant select on public.rental_collection_preferences,public.rental_collection_reminders to authenticated;
create policy rental_collection_preferences_read on public.rental_collection_preferences for select to authenticated using(exists(select 1 from public.rental_tenancies t join public.rental_properties p on p.id=t.property_id where t.id=tenancy_id and public.rental_branch_access(p.organisation_id,p.branch_id)));
create policy rental_collection_reminders_read on public.rental_collection_reminders for select to authenticated using(exists(select 1 from public.rental_tenancies t join public.rental_properties p on p.id=t.property_id where t.id=tenancy_id and public.rental_branch_access(p.organisation_id,p.branch_id)));
create or replace function public.rental_tenancy_live_outstanding(p_tenancy uuid) returns numeric language sql stable security definer set search_path='' as $$select coalesce((select sum(amount) from public.rental_financial_charges where tenancy_id=p_tenancy),0)-coalesce((select sum(amount) from public.rental_financial_allocations where tenancy_id=p_tenancy),0)+coalesce((select sum(amount) from public.rental_financial_adjustments where tenancy_id=p_tenancy and adjustment_type='debit'),0)-coalesce((select sum(amount) from public.rental_financial_adjustments where tenancy_id=p_tenancy and adjustment_type='credit'),0)$$;
create or replace function public.rental_queue_collection_reminder(p_tenancy uuid,p_stage text) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.rental_tenancies%rowtype;p public.rental_collection_preferences%rowtype;bal numeric;rid uuid;begin if auth.uid() is null or p_stage not in('current','overdue_7','overdue_30','overdue_60','overdue_90') then raise exception 'Valid reminder stage required';end if;select * into t from public.rental_tenancies where id=p_tenancy for update;if not found or not exists(select 1 from public.rental_properties x where x.id=t.property_id and public.rental_branch_access(x.organisation_id,x.branch_id)) then raise exception 'Not authorized';end if;bal:=public.rental_tenancy_live_outstanding(t.id);if bal<=0 then raise exception 'No reminder: tenancy has no live outstanding balance';end if;select * into p from public.rental_collection_preferences where tenancy_id=t.id; if p.channel='none' or p.suppressed_until>now() then insert into public.rental_collection_reminders(organisation_id,tenancy_id,reminder_stage,channel,status,balance_snapshot,suppressed_reason,created_by) values(t.organisation_id,t.id,p_stage,coalesce(p.channel,'email'),'suppressed',bal,coalesce(p.suppression_reason,'Suppressed'),auth.uid()) on conflict do nothing returning id into rid;else insert into public.rental_collection_reminders(organisation_id,tenancy_id,reminder_stage,channel,balance_snapshot,created_by) values(t.organisation_id,t.id,p_stage,coalesce(p.channel,'email'),bal,auth.uid()) on conflict do nothing returning id into rid;end if;return jsonb_build_object('reminder_id',rid,'live_balance',bal);end$$;
create or replace function public.rental_send_collection_reminder(p_reminder uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.rental_collection_reminders%rowtype;bal numeric;begin select * into r from public.rental_collection_reminders where id=p_reminder for update;if not found then raise exception 'Reminder not found';end if;bal:=public.rental_tenancy_live_outstanding(r.tenancy_id);if r.status<>'queued' then return jsonb_build_object('reminder_id',r.id,'status',r.status,'idempotent',true);end if;if bal<=0 then update public.rental_collection_reminders set status='cancelled',suppressed_reason='Balance cleared before send' where id=r.id;return jsonb_build_object('reminder_id',r.id,'status','cancelled');end if;update public.rental_collection_reminders set status='sent',sent_at=now(),balance_snapshot=bal where id=r.id;return jsonb_build_object('reminder_id',r.id,'status','sent','live_balance',bal);end$$;
create or replace function public.rental_suppress_collection_reminders(p_tenancy uuid,p_until timestamptz,p_reason text) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.rental_tenancies%rowtype;begin select * into t from public.rental_tenancies where id=p_tenancy for update;if not found or not exists(select 1 from public.rental_properties x where x.id=t.property_id and public.rental_branch_access(x.organisation_id,x.branch_id)) then raise exception 'Not authorized';end if;if p_until is null or p_until<=now() or length(btrim(coalesce(p_reason,'')))=0 then raise exception 'Future suppression end and reason required';end if;insert into public.rental_collection_preferences(organisation_id,tenancy_id,suppressed_until,suppression_reason,updated_by) values(t.organisation_id,t.id,p_until,btrim(p_reason),auth.uid()) on conflict(tenancy_id) do update set suppressed_until=excluded.suppressed_until,suppression_reason=excluded.suppression_reason,updated_by=excluded.updated_by,updated_at=now();return jsonb_build_object('tenancy_id',t.id,'suppressed_until',p_until);end$$;
revoke execute on function public.rental_tenancy_live_outstanding(uuid),public.rental_queue_collection_reminder(uuid,text),public.rental_send_collection_reminder(uuid),public.rental_suppress_collection_reminders(uuid,timestamptz,text) from public,anon;grant execute on function public.rental_queue_collection_reminder(uuid,text),public.rental_send_collection_reminder(uuid),public.rental_suppress_collection_reminders(uuid,timestamptz,text) to authenticated;commit;
